story=[]
def clean(s):
 s=str(s).replace('–','-').replace('—','-').replace('‑','-')
 units=r'(?:km|kg|mN|nN|µN|W|m/s|ms\b|s\b|arcsec|cm|rpm|Hz|µT|nT|days?\b|m²|m³|g\b)'
 s=re.sub(r'(?<=[A-Za-z])(?=\d+(?:\.\d+)?'+units+')',' ',s)
 return re.sub(r'(?<=\d)(?='+units+')',' ',s).replace('DE 440 s','DE440s')
def p(s,style='BodyX'):story.append(Paragraph(clean(s),styles[style]))
def head(s):p(s,'HeadX')
def sub(s):p(s,'SubX')
def page():story.append(PageBreak())
def table(headers,rows,widths):
 data=[[Paragraph(html.escape(clean(x)),styles['CellH'])for x in headers]]+[[Paragraph(html.escape(clean(x)),styles['CellX'])for x in row]for row in rows]
 t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#344D70')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#EFF2F6')]),('LINEBELOW',(0,0),(-1,0),.5,colors.white)]));story.extend([t,Spacer(1,9)])
def fig(name,width=500,height=207):story.extend([Image(str(ROOT/'figures/disturbance_environment'/name),width=width,height=height),Spacer(1,7)])
